source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    background = counts.most_common(1)[0][0]
    colors = [x for x in counts if x != background]
    marker = max(colors, key=lambda x: counts[x])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    row_points = {r: sorted(c for rr, c in points if rr == r) for r in range(h)}
    col_points = {c: sorted(r for r, cc in points if cc == c) for c in range(w)}
    active_rows = {r for r, cs in row_points.items() if len(cs) >= 4}
    active_cols = {c for c, rs in col_points.items() if len(rs) >= 4}
    changed = True
    while changed:
        changed = False
        for r, cs in row_points.items():
            if len(cs) == 3 and r not in active_rows and (cs[0] in active_cols or cs[-1] in active_cols):
                active_rows.add(r)
                changed = True
        for c, rs in col_points.items():
            if len(rs) == 3 and c not in active_cols and (rs[0] in active_rows or rs[-1] in active_rows):
                active_cols.add(c)
                changed = True
    out = [row[:] for row in grid]
    for r in active_rows:
        cs = row_points[r]
        for c in range(cs[0], cs[-1] + 1):
            if out[r][c] != marker:
                out[r][c] = 2
    for c in active_cols:
        rs = col_points[c]
        for r in range(rs[0], rs[-1] + 1):
            if out[r][c] != marker:
                out[r][c] = 2
    return out
